using System;
namespace SarmatVisionHold.Core { public static class FlowQualityEstimator { static bool F(double v)=>!double.IsNaN(v)&&!double.IsInfinity(v);public static double Estimate(int tracked,int detected,double medianError){ if(detected<=0||tracked<=0||!F(medianError))return 0; var retention=Math.Min(1d,(double)tracked/detected); var error=Math.Exp(-Math.Max(0,medianError)/12d); return Math.Max(0,Math.Min(1,retention*error)); } public static bool Pass(FlowSample f,VisionHoldSettings s)=>f!=null&&f.TrackedPoints>=s.MinimumTrackedPoints&&F(f.Quality)&&f.Quality>=s.MinimumFlowQuality&&F(f.Fps)&&f.Fps>=s.MinimumFps&&F(f.FrameAgeMs)&&f.FrameAgeMs>=0&&f.FrameAgeMs<=s.MaxFrameAgeMs; } }
